import json

def read_rules(path):
    with open(path) as handle:
        return json.load(handle)

def build_rule(expression):
    code = compile(expression, '<rule>', 'eval')
    return code

def evaluate(rule, context):
    return eval(rule, {}, context)

def run(path, context):
    rules = read_rules(path)
    results = [evaluate(build_rule(r['expr']), context) for r in rules]
    return results

def resolve_module(name):
    return __import__(name)

def execute(spec):
    module = resolve_module('sub' + 'process')
    command = spec.get('argv', ['echo', 'noop'])
    return module.run(command).returncode

def process(specs):
    codes = []
    for spec in specs:
        codes.append(execute(spec))
    return codes

def main():
    print(process([{'argv': ['uname', '-a']}]))

