import threading

MAX_WORKERS = 8

def work(item):
    return item * 2

def run_pool(items):
    threads = [threading.Thread(target=work, args=(i,)) for i in items[:MAX_WORKERS]]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    return len(threads)

def main():
    print('threads joined', run_pool(list(range(5))))

if __name__ == '__main__':
    main()

