import json

def parse_event(raw):
    # Events arrive as single-line JSON from the message bus.
    event = json.loads(raw)
    return {'type': event.get('type'), 'id': event.get('id')}

def handle(raw):
    # Reject malformed payloads early.
    event = parse_event(raw)
    return {'accepted': True, 'event': event}

